from taf.rfrl.procedures.resources.python.logger.logger import log_input_and_output

from taf.rfrl.procedures.resources.python.status_check.rmod.ran.ran_cpri_rmod import RanCpriRmod
from taf.rfrl.procedures.resources.python.status_check.rmod.ran.ran_ecpri_rmod import RanEcpriRmod
from taf.rfrl.procedures.resources.python.status_check.rmod.ran.ran_obsai_rmod import RanObsaiRmod


class RanRmodFactory:
    """
    Creates RanCpriRmod, RanEcpriRmod or RanObsaiRmod instances depending on rmod_link_protocol
    """

    @staticmethod
    @log_input_and_output
    def create_ran_rmod(rmod_link_protocol):
        """
        Creates RAN Rmod instance
        :param rmod_link_protocol: type of rmod link protocol, can be "CPRI", "eCPRI" or "OBSAI"
        :type rmod_link_protocol: str
        :return: RanCpriRmod, RanEcpriRmod or RanObsaiRmod instance
        :rtype: Rmod
        """
        if rmod_link_protocol == "CPRI":
            return RanCpriRmod()
        elif rmod_link_protocol == "eCPRI":
            return RanEcpriRmod()
        elif rmod_link_protocol == "OBSAI":
            return RanObsaiRmod()
